    function sequence(depth,closing){let steps=[];separators();while(cursor<tokens.length){const token=tokens[cursor],word=token.value;if(word==='}'){if(!closing)fail('This closing } has no matching repeat block.');cursor++;return steps;}if(word==='repeat'){cursor++;blocks++;if(depth>=3)fail('Use no more than 3 nested repeat blocks.');const countToken=tokens[cursor];if(!countToken||!/^\d+$/.test(countToken.value))fail('Write a repeat count, such as repeat 2 { east 1 }.');const count=Number(countToken.value);if(count<1||count>8)fail('Repeat counts must be between 1 and 8.',countToken);cursor++;if(tokens[cursor]?.value!=='{')fail('Add { after the repeat count, then close the block with }.');cursor++;const inner=sequence(depth+1,true);if(!inner.length)fail('This repeat block is empty. Add at least one movement.',token);for(let r=0;r<count;r++)for(const step of inner)steps.push({...step,repeat:[`loop ${r+1}/${count}`,...step.repeat]});}else{const dir=({up:'north',down:'south',left:'west',right:'east'})[word]||word;if(!['north','south','east','west'].includes(dir))fail(`“${word}” is not a direction or repeat command. Use north, south, east, west, or repeat.`);cursor++;blocks++;let count=1;if(tokens[cursor]&&/^\d+$/.test(tokens[cursor].value)){count=Number(tokens[cursor].value);cursor++;}if(count<1||count>7)fail('A movement instruction needs 1–7 steps.',token);const line=source.slice(0,token.position).split('\n').length;for(let n=0;n<count;n++)steps.push({dir,label:`${dir} ${count}`,within:`${n+1}/${count}`,line,repeat:[]});}if(steps.length>80)fail('The expanded program exceeds 80 moves. Reduce the repeat counts.');separators();}if(closing)fail('This repeat block is missing its closing }.');return steps;}
