    function pointer(event){if(running||disposed)return;const r=canvas.getBoundingClientRect(),x=(event.clientX-r.left)*W/r.width,y=(event.clientY-r.top)*H/r.height;for(const[name,point]of Object.entries(cfg.positions)){const mx=ox+(point.x+.5)*s,my=oy+(point.y+.5)*s;if(Math.hypot(mx-x,my-y)<28){mirrors[name]=mirrors[name]==='/'?'\\':'/';turns++;trace=null;won=false;stats();draw();message(`Mirror ${name} rotated. Fire the beam to inspect the new route.`);onEvent({type:'milestone',message:`Rotated mirror ${name}.`,command:`rotate ${name}`});sound(sfx,'move');return;}}}
